import re,json
h=open('/tmp/p.html',encoding='utf-8').read()
print('p tags',len(re.findall(r'<p[ >]',h)), 'article', '<article' in h, 'main', '<main' in h)
m=re.search(r'<script id="__NEXT_DATA__"[^>]*>(.*?)</script>',h,re.S)
print('next data', bool(m), len(m.group(1)) if m else 0)
d=json.loads(m.group(1))
def walk(n,path,out):
    if isinstance(n,dict):
        for k,v in n.items(): walk(v,path+'.'+k,out)
    elif isinstance(n,list):
        for i,v in enumerate(n): walk(v,path+f'[{i}]',out)
    elif isinstance(n,str) and len(n)>300: out.append((path,n[:150]))
out=[];walk(d,'',out)
for p,t in out[:25]: print(p,'|',t.replace('\n',' '))
print(len(out))
EOF

